          labels: ['Veolia', 'SUEZ', 'Ecolab', 'Xylem', 'Kurita', 'WABAG', 'Thermax', 'Aquatech', 'Gradiant', 'Ion Exchange', 'IDE Tech', 'TRITRON™'],
